#' Bounds under Attrition
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param control .
#' @param armTreat .
#' @param tight .
#' @param direction .
#' @param level .
#' @param nboot .
#' @param seed .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$sel} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$sel$asDF}
#'
#' \code{as.data.frame(results$sel)}
#'
#' @export
exlee <- function(
    data,
    outcome,
    treat,
    control = "",
    armTreat = "",
    tight,
    direction = "auto",
    level = 95,
    nboot = 1000,
    seed = 1234,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exlee requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(tight)) tight <- jmvcore::resolveQuo(jmvcore::enquo(tight))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(tight), tight, NULL))


    options <- exleeOptions$new(
        outcome = outcome,
        treat = treat,
        control = control,
        armTreat = armTreat,
        tight = tight,
        direction = direction,
        level = level,
        nboot = nboot,
        seed = seed,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exleeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

